//! Traductions de l'interface : français (clé), anglais, espagnol, allemand.
//! La clé est le texte français ; une clé absente du tableau s'affiche telle quelle.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
/// Langue de l'interface.
pub enum Lang {
    /// Français.
    Fr,
    /// Anglais.
    En,
    /// Espagnol.
    Es,
    /// Allemand.
    De,
}

impl Lang {
    /// Nom de la langue dans cette langue.
    pub fn name(self) -> &'static str {
        match self {
            Lang::Fr => "Français",
            Lang::En => "English",
            Lang::Es => "Español",
            Lang::De => "Deutsch",
        }
    }
    /// Code ISO à deux lettres.
    pub fn code(self) -> &'static str {
        match self {
            Lang::Fr => "FR",
            Lang::En => "EN",
            Lang::Es => "ES",
            Lang::De => "DE",
        }
    }
}

static CURRENT: AtomicU8 = AtomicU8::new(0);

/// Fixe la langue utilisée par `tr`.
pub fn set_lang(l: Lang) {
    CURRENT.store(l as u8, Ordering::Relaxed);
}

/// Langue courante de l'interface.
pub fn current() -> Lang {
    match CURRENT.load(Ordering::Relaxed) {
        1 => Lang::En,
        2 => Lang::Es,
        3 => Lang::De,
        _ => Lang::Fr,
    }
}

/// Traduction dans la langue courante (pour les fonctions d'aide graphiques).
pub fn tr(k: &'static str) -> &'static str {
    T(current(), k)
}

#[allow(non_snake_case)]
/// Traduction de la clé `k` (texte français) dans la langue `l`.
pub fn T(l: Lang, k: &'static str) -> &'static str {
    if l == Lang::Fr {
        return k;
    }
    static MAP: OnceLock<HashMap<&'static str, [&'static str; 3]>> = OnceLock::new();
    let m = MAP.get_or_init(|| TABLE.iter().chain(crate::repartition::extra_translations()).map(|(f, e, s, d)| (*f, [*e, *s, *d])).collect());
    match m.get(k) {
        Some(v) => v[l as usize - 1],
        None => k,
    }
}

