#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn pas_de_doublon_et_traductions_non_vides() {
        let mut seen = std::collections::HashSet::new();
        for (f, e, s, d) in TABLE {
            assert!(seen.insert(*f), "doublon : {f}");
            assert!(!e.is_empty() && !s.is_empty() && !d.is_empty(), "{f}");
        }
    }
    /// Extrait les chaînes passées à `t(…)`, `tr(…)`, `T(lang, …)` dans le code.
    fn cles_du_code(src: &str) -> Vec<String> {
        let mut out = Vec::new();
        let pats = ["t(\"", "tt(\"", "tr(\"", "T(lang, \"", "T(self.cfg.lang, \"", "T(d.lang, \""];
        let b = src.as_bytes();
        for p in pats {
            let mut from = 0;
            while let Some(k) = src[from..].find(p) {
                let start = from + k + p.len();
                // `t(` doit être un appel isolé (pas la fin d'un autre identifiant)
                let prev = if from + k > 0 { b[from + k - 1] } else { b' ' };
                let ok = p.starts_with('T') || !(prev.is_ascii_alphanumeric() || prev == b'_');
                let mut i = start;
                let mut lit = String::new();
                while i < b.len() && b[i] != b'"' {
                    if b[i] == b'\\' {
                        i += 1;
                    }
                    let c = src[i..].chars().next().unwrap();
                    lit.push(c);
                    i += c.len_utf8();
                }
                if ok && !lit.is_empty() {
                    out.push(lit);
                }
                from = i.min(src.len());
            }
        }
        out
    }

    #[test]
    fn toutes_les_cles_de_l_interface_sont_traduites() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut fichiers: Vec<_> = std::fs::read_dir(dir.join("app")).unwrap().map(|e| e.unwrap().path()).collect();
        fichiers.push(dir.join("doc.rs"));
        fichiers.push(dir.join("script.rs"));
        fichiers.push(dir.join("optimize.rs"));
        let mut manquantes = std::collections::BTreeSet::new();
        for f in fichiers {
            let src = std::fs::read_to_string(&f).unwrap();
            for k in cles_du_code(&src) {
                if !TABLE.iter().any(|(fr, _, _, _)| *fr == k) {
                    manquantes.insert(format!("{} : {k}", f.file_name().unwrap().to_string_lossy()));
                }
            }
        }
        assert!(manquantes.is_empty(), "clés non traduites : {manquantes:#?}");
    }
}
